  const [shiftsExternes, setShiftsExternes] = useListeExterne(identiteExterne, "shifts");
  const shifts = modeExterne ? shiftsExternes : shiftsStockes;
  const setShifts = modeExterne ? setShiftsExternes : setShiftsStockes;
  // Tâches : en prévisualisation, en mémoire seulement (jamais l'ancien stockage, qui contient les tâches réelles de
  // Games Factory) et sans les tâches Games Factory intégrées au code. Deux tâches génériques d'exemple sont proposées
  // pour pouvoir essayer le test d'huile ; le chef peut en créer d'autres. La vraie migration des tâches viendra plus tard.
  const [tasksStockees, setTasksStockees] = useStored("taches", DEFAULT_TASKS_POSTE_CHAUD);
  const [tasksExternes, setTasksExternes] = useState(() => [
    { id: uid(), titre: "Filtrer ou changer l'huile de la friteuse", heure: "10:00", duree: 15, categorie: "Nettoyage", assignedTo: "tous", recurrence: "Quotidienne", jour: "Lundi", date: null, declencheChangementHuile: true, completions: {} },
    { id: uid(), titre: "Nettoyage de fin de service", heure: "21:30", duree: 60, categorie: "Nettoyage", assignedTo: "tous", recurrence: "Quotidienne", jour: "Lundi", date: null, declencheHuile: true, completions: {} },
  ]);
  const tasks = modeExterne ? tasksExternes : tasksStockees;
  const setTasks = modeExterne ? setTasksExternes : setTasksStockees;
  // Catalogue des préparations maison : en prévisualisation, vide et en mémoire (pas celui de Games Factory) — fiches/traçabilité pas encore migrées.
  const [produitsMemoire, setProduitsMemoire] = useStoredOuMemoire("produits-catalogue", DEFAULT_PRODUITS, modeExterne, []);
  // En prévisualisation : le catalogue DLC / étiquettes vient des produits de la nouvelle base (durée de conservation saisie dans la fiche produit).
  const catalogueExterne = modeExterne && identiteExterne ? identiteExterne.catalogue : null;
  const produitsCatalogueExterne = React.useMemo(() => {
    const cat = catalogueExterne || [];
    const CAT_PAR_TYPE = { surgele: "Surgelés", viande: "Viandes", poisson: "Poissons", legume: "Fruits et légumes" };
    return cat.filter((c) => !["entretien", "emballage", "autre"].includes(c.conservation)).map((c) => {
      const jours = c.dlcJours == null ? null : Number(c.dlcJours);
      return {
        id: c.id, nom: c.nom, poste: "", categorieManuelle: CAT_PAR_TYPE[c.conservation] || (ORDRE_CATEGORIES_DLC.includes(c.categorie) ? c.categorie : null),
        typeDate: c.typeDate || (jours != null ? "DLC" : "DDM"), dlcJours: jours,
        ddmLotActuel: c.lot || null, ddmDateActuelle: c.dlc || null,
      };
    });
  }, [catalogueExterne]);
  const produits = modeExterne ? produitsCatalogueExterne : produitsMemoire;
  const setProduits = modeExterne ? (() => {}) : setProduitsMemoire;
  const [horairesStockes, setHorairesStockes] = useStored("horaires-service", []);
  const [horairesExternes, setHorairesExternes] = useListeExterne(identiteExterne, "horaires");
  const horaires = modeExterne ? horairesExternes : horairesStockes;
  const setHoraires = modeExterne ? setHorairesExternes : setHorairesStockes;
  const [cartesStockees, setCartesStockees] = useStored("cartes", []);
